      "style": ".fr{height:100%;box-sizing:border-box;display:grid;grid-template-columns:38px 1fr;gap:8px;align-items:center;padding:6px 8px;background:#fff4ef;border:2px solid #c62f22;font-family:\"Pretendard\", \"Malgun Gothic\", \"Apple SD Gothic Neo\", sans-serif;color:#1f1d1a}\n.sym{width:34px;height:34px;box-sizing:border-box;border:3px solid #c62f22;border-radius:50%;background:linear-gradient(#c62f22,#c62f22) center/3px 100% no-repeat,linear-gradient(#c62f22,#c62f22) center/100% 3px no-repeat}\nh2{margin:0;font-size:15px;font-weight:800;color:#c62f22;white-space:nowrap}\np{margin:1px 0 0;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}",
