      "style": ".tb{height:100%;box-sizing:border-box;padding:4px 4px 0;font-family:\"Pretendard\", \"Malgun Gothic\", \"Apple SD Gothic Neo\", sans-serif;color:#1f1d1a}\n.sheet{margin:0;font-size:12px;letter-spacing:.12em;color:#5a564e}\nh1{margin:2px 0 0;font-family:\"Nanum Myeongjo\", \"Batang\", \"AppleMyungjo\", serif;font-size:40px;font-weight:800;letter-spacing:.3em}\n.when{margin:2px 0 8px;font-size:13px;color:#5a564e}\n.risk{margin:0;padding:6px 10px;border:1.5px solid #1f1d1a;font-size:14px;display:flex;align-items:baseline;gap:8px}\n.risk b{font-size:20px}.risk small{font-size:12px;color:#5a564e;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.high{border-color:#c62f22;border-width:3px}.high b{color:#c62f22}",
